// analyzer/constructorTransform.ts:42
pub fn has_constructor_transform(class_type: ClassType) -> bool {
    if class_type.d().shared.get().full_name == jsrt::atom!("functools.partial") {
        return true;
    }

    false
}

// analyzer/constructorTransform.ts:50
pub fn apply_constructor_transform(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    class_type: ClassType,
    result: &FunctionResult,
) -> Option<FunctionResult> {
    if class_type.d().shared.get().full_name == jsrt::atom!("functools.partial") {
        return apply_partial_transform(evaluator, error_node, arg_list, result);
    }

    // By default, return the result unmodified.
    Some(result.clone())
}

// analyzer/constructorTransform.ts:66
// Applies a transform for the functools.partial class constructor.
pub(crate) fn apply_partial_transform(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    result: &FunctionResult,
) -> Option<FunctionResult> {
    // We assume that the normal return result is a functools.partial class instance.
    if !is_class_instance(result.return_type)
        || ClassType(result.return_type).d().shared.get().full_name != jsrt::atom!("functools.partial")
    {
        return None;
    }
    let result_class = ClassType(result.return_type);

    let type_same_options = TypeSameOptions::default();
    let call_member_result = look_up_object_member(
        result_class,
        "__call__",
        MemberAccessFlags::SkipInstanceMembers,
        None,
    )?;
    if !is_type_same(
        convert_to_instance(call_member_result.class_type, true),
        result.return_type,
        &type_same_options,
        0,
    ) {
        return None;
    }

    let call_member_type = evaluator.get_type_of_member(&call_member_result);
    if !is_function(call_member_type)
        || FunctionType(call_member_type)
            .d()
            .shared
            .get()
            .parameters
            .get()
            .borrow()
            .is_empty()
    {
        return None;
    }
    let call_member_type = FunctionType(call_member_type);

    if arg_list.is_empty() {
        return None;
    }

    let orig_function_type_result =
        evaluator.get_type_of_arg(&arg_list[0], /* inferenceContext */ None);
    let mut orig_function_type = orig_function_type_result.type_.get();
    let orig_function_type_concrete =
        evaluator.make_top_level_type_vars_concrete(orig_function_type, false, None);

    if is_instantiable_class(orig_function_type_concrete) {
        let constructor = create_function_from_constructor(
            evaluator,
            ClassType(orig_function_type_concrete),
            if is_type_var(orig_function_type) {
                Some(convert_to_instance(orig_function_type, true))
            } else {
                None
            },
            0,
        );

        if let Some(constructor) = constructor {
            orig_function_type = constructor;
        }
    } else if is_class_instance(orig_function_type_concrete) {
        let call_method_result = evaluator.get_type_of_bound_member(
            Some(error_node),
            ClassType(orig_function_type_concrete),
            jsrt::atom!("__call__"),
            /* usage */
            &EvaluatorUsage {
                method: "get".to_string(),
                set_type: None,
                set_error_node: None,
                set_expected_type_diag: None,
            },
            /* diag */ None,
            MemberAccessFlags::SkipInstanceMembers | MemberAccessFlags::SkipAttributeAccessOverride,
            None,
            0,
        );
        if let Some(call_method_result) = call_method_result {
            let call_method_type = call_method_result.type_.get();
            if is_function(call_method_type) || is_overloaded(call_method_type) {
                orig_function_type = call_method_type;
            }
        }
    }

    // Evaluate the inferred return type if necessary.
    evaluator.infer_return_type_if_necessary(orig_function_type);

    // We don't currently handle unpacked arguments.
    if arg_list
        .iter()
        .any(|arg| arg.arg_category() != ArgCategory::Simple)
    {
        return None;
    }

    // Make sure the first argument is a simple function.
    if is_function(orig_function_type) {
        let transform_result = apply_partial_transform_to_function(
            evaluator,
            Some(error_node),
            arg_list,
            call_member_type,
            FunctionType(orig_function_type),
        )?;

        // Create a new copy of the functools.partial class that overrides the __call__ method.
        let new_partial_class =
            ClassType::clone_for_partial(result_class, transform_result.return_type);

        return Some(FunctionResult {
            return_type: new_partial_class.0,
            is_type_incomplete: result.is_type_incomplete,
            argument_errors: transform_result.argument_errors,
        });
    }

    if is_overloaded(orig_function_type) {
        let mut applicable_overloads: Vec<FunctionType> = Vec::new();
        let overloads = OverloadedType::get_overloads(OverloadedType(orig_function_type));
        let mut saw_arg_errors = false;

        // Apply the partial transform to each of the functions in the overload.
        for &overload in &overloads {
            // Apply the transform to this overload, but don't report errors.
            let transform_result = apply_partial_transform_to_function(
                evaluator,
                /* errorNode */ None,
                arg_list,
                call_member_type,
                overload,
            );

            if let Some(transform_result) = transform_result {
                if transform_result.argument_errors {
                    saw_arg_errors = true;
                } else if is_function(transform_result.return_type) {
                    applicable_overloads.push(FunctionType(transform_result.return_type));
                }
            }
        }

        if applicable_overloads.is_empty() {
            if saw_arg_errors && !overloads.is_empty() {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportCallIssue,
                    &LocMessage::no_overload()
                        .format(&[("name", &overloads[0].d().shared.get().name)]),
                    error_node,
                    None,
                );
            }

            return None;
        }

        let synthesized_call_type: P<Type> = if applicable_overloads.len() == 1 {
            applicable_overloads[0].0
        } else {
            OverloadedType::create(
                // Set the "overloaded" flag for each of the __call__ overloads.
                &applicable_overloads
                    .iter()
                    .map(|&overload| {
                        FunctionType::clone_with_new_flags(
                            overload,
                            overload.d().shared.get().flags.get() | FunctionTypeFlags::Overloaded,
                        )
                    })
                    .collect::<Vec<_>>(),
                None,
            )
            .0
        };

        // Create a new copy of the functools.partial class that overrides the __call__ method.
        let new_partial_class = ClassType::clone_for_partial(result_class, synthesized_call_type);

        return Some(FunctionResult {
            return_type: new_partial_class.0,
            is_type_incomplete: result.is_type_incomplete,
            argument_errors: false,
        });
    }

    None
}

// analyzer/constructorTransform.ts:214
pub(crate) fn apply_partial_transform_to_function(
    evaluator: &TypeEvaluator,
    error_node: Option<ExpressionNode>,
    arg_list: &[Arg],
    partial_call_member_type: FunctionType,
    orig_function_type: FunctionType,
) -> Option<FunctionResult> {
    // Create a map to track which parameters have supplied arguments.
    let mut param_map: JsMap<String, bool> = JsMap::default();

    let param_list_details = get_param_list_details(orig_function_type, None);

    // Verify the types of the provided arguments.
    let mut argument_errors = false;
    let mut reported_positional_error = false;
    let constraints = ConstraintTracker::new();

    let orig_function_name = orig_function_type.d().shared.get().name;

    let remaining_args_list = arg_list.get(1..).unwrap_or(&[]);
    for (arg_index, arg) in remaining_args_list.iter().enumerate() {
        let Some(value_expression) = arg.value_expression() else {
            continue;
        };

        // Is it a positional argument or a keyword argument?
        let Some(arg_name) = arg.name() else {
            // Does this positional argument map to a positional parameter?
            if arg_index >= param_list_details.params.len()
                || param_list_details.params[arg_index].kind == ParamKind::Keyword
            {
                if let Some(args_index) = param_list_details.args_index {
                    let args_param = param_list_details.params[args_index as usize];
                    let param_type =
                        FunctionType::get_param_type(orig_function_type, args_param.index);
                    let diag = DiagnosticAddendum::new();

                    let inference_context =
                        make_inference_context(Some(param_type), None, None);
                    let arg_type_result = evaluator.get_type_of_expression(
                        value_expression,
                        /* flags */ EvalFlags::None,
                        inference_context,
                    );

                    if !evaluator.assign_type(
                        param_type,
                        arg_type_result.type_.get(),
                        Some(diag),
                        Some(constraints),
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        if error_node.is_some() {
                            evaluator.add_diagnostic(
                                DiagnosticRule::reportArgumentType,
                                &LocMessage::arg_assignment_param_function().format(&[
                                    (
                                        "argType",
                                        &evaluator.print_type(arg_type_result.type_.get(), None),
                                    ),
                                    ("paramType", &evaluator.print_type(param_type, None)),
                                    ("functionName", &orig_function_name),
                                    ("paramName", args_param.param.name.as_deref().unwrap_or("")),
                                ]),
                                value_expression,
                                None,
                            );
                        }

                        argument_errors = true;
                    }
                } else {
                    // Don't report multiple positional errors.
                    if !reported_positional_error {
                        if error_node.is_some() {
                            evaluator.add_diagnostic(
                                DiagnosticRule::reportCallIssue,
                                &if param_list_details.position_param_count == 1 {
                                    LocMessage::arg_positional_expected_one()
                                } else {
                                    LocMessage::arg_positional_expected_count().format(&[(
                                        "expected",
                                        &number_to_string(
                                            param_list_details.position_param_count as f64,
                                        ),
                                    )])
                                },
                                value_expression,
                                None,
                            );
                        }
                    }

                    reported_positional_error = true;
                    argument_errors = true;
                }
            } else {
                let param_info = param_list_details.params[arg_index];
                let param_type = param_info.type_;
                let diag = DiagnosticAddendum::new();
                let param_name = param_info.param.name.as_deref().unwrap_or_default().to_string();

                let inference_context = make_inference_context(Some(param_type), None, None);
                let arg_type_result = evaluator.get_type_of_expression(
                    value_expression,
                    /* flags */ EvalFlags::None,
                    inference_context,
                );

                if !evaluator.assign_type(
                    param_type,
                    arg_type_result.type_.get(),
                    Some(diag),
                    Some(constraints),
                    AssignTypeFlags::Default,
                    0,
                ) {
                    if error_node.is_some() {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportArgumentType,
                            &LocMessage::arg_assignment_param_function().format(&[
                                (
                                    "argType",
                                    &evaluator.print_type(arg_type_result.type_.get(), None),
                                ),
                                ("paramType", &evaluator.print_type(param_type, None)),
                                ("functionName", &orig_function_name),
                                ("paramName", &param_name),
                            ]),
                            value_expression,
                            None,
                        );
                    }

                    argument_errors = true;
                }

                // Mark the parameter as assigned.
                param_map.insert(param_name, false);
            }
            continue;
        };

        let arg_name_value = arg_name.d().value();
        let matching_param = param_list_details
            .params
            .iter()
            .copied()
            .find(|param_info| {
                param_info.param.name.as_deref() == Some(arg_name_value)
                    && param_info.kind != ParamKind::Positional
            });

        let Some(matching_param) = matching_param else {
            // Is there a kwargs parameter?
            let Some(kwargs_index) = param_list_details.kwargs_index else {
                if error_node.is_some() {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportCallIssue,
                        &LocMessage::param_name_missing().format(&[("name", arg_name_value)]),
                        arg_name.0,
                        None,
                    );
                }
                argument_errors = true;
                continue;
            };

            let kwargs_param = param_list_details.params[kwargs_index as usize];
            let param_type = FunctionType::get_param_type(orig_function_type, kwargs_param.index);
            let diag = DiagnosticAddendum::new();

            let inference_context = make_inference_context(Some(param_type), None, None);
            let arg_type_result = evaluator.get_type_of_expression(
                value_expression,
                /* flags */ EvalFlags::None,
                inference_context,
            );

            if !evaluator.assign_type(
                param_type,
                arg_type_result.type_.get(),
                Some(diag),
                Some(constraints),
                AssignTypeFlags::Default,
                0,
            ) {
                if error_node.is_some() {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportArgumentType,
                        &LocMessage::arg_assignment_param_function().format(&[
                            (
                                "argType",
                                &evaluator.print_type(arg_type_result.type_.get(), None),
                            ),
                            ("paramType", &evaluator.print_type(param_type, None)),
                            ("functionName", &orig_function_name),
                            (
                                "paramName",
                                kwargs_param.param.name.as_deref().unwrap_or(""),
                            ),
                        ]),
                        value_expression,
                        None,
                    );
                }

                argument_errors = true;
            }
            continue;
        };

        let param_name = matching_param.param.name.as_deref().unwrap().to_string();
        let param_type = matching_param.type_;

        if param_map.contains_key(&param_name) {
            if error_node.is_some() {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportCallIssue,
                    &LocMessage::param_already_assigned().format(&[("name", arg_name_value)]),
                    arg_name.0,
                    None,
                );
            }

            argument_errors = true;
        } else {
            let diag = DiagnosticAddendum::new();

            let inference_context = make_inference_context(Some(param_type), None, None);
            let arg_type_result = evaluator.get_type_of_expression(
                value_expression,
                /* flags */ EvalFlags::None,
                inference_context,
            );

            if !evaluator.assign_type(
                param_type,
                arg_type_result.type_.get(),
                Some(diag),
                Some(constraints),
                AssignTypeFlags::Default,
                0,
            ) {
                if error_node.is_some() {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportArgumentType,
                        &LocMessage::arg_assignment_param_function().format(&[
                            (
                                "argType",
                                &evaluator.print_type(arg_type_result.type_.get(), None),
                            ),
                            ("paramType", &evaluator.print_type(param_type, None)),
                            ("functionName", &orig_function_name),
                            ("paramName", &param_name),
                        ]),
                        value_expression,
                        None,
                    );
                }

                argument_errors = true;
            }
            param_map.insert(param_name, true);
        }
    }

    let specialized_function_type =
        evaluator.solve_and_apply_constraints(orig_function_type.0, constraints, None, None);
    if !is_function(specialized_function_type) {
        return None;
    }
    let specialized_function_type = FunctionType(specialized_function_type);
    let specialized_shared = specialized_function_type.d().shared.get();

    // Create a new parameter list that omits parameters that have been
    // populated already.
    let specialized_params = specialized_shared.parameters.get().borrow().clone();
    let updated_param_list: Vec<FunctionParam> = specialized_params
        .iter()
        .enumerate()
        .map(|(index, param)| {
            let mut new_type =
                FunctionType::get_param_type(specialized_function_type, index as i32);

            // If this is an **kwargs with an unpacked TypedDict, mark the provided
            // TypedDict entries as provided.
            if param.category == ParamCategory::KwargsDict
                && is_class_instance(new_type)
                && is_unpacked_class(new_type)
                && ClassType::is_typed_dict_class(ClassType(new_type))
            {
                let typed_dict_entries =
                    get_typed_dict_members_for_class(evaluator, ClassType(new_type), false);
                let mut narrowed_entries_map: JsMap<String, TypedDictEntry> = ClassType(new_type)
                    .d()
                    .priv_
                    .borrow()
                    .cold().typed_dict_narrowed_entries
                    .clone()
                    .unwrap_or_default();

                for (name, entry) in typed_dict_entries.known_items.borrow().iter() {
                    if param_map.contains_key(name) {
                        narrowed_entries_map.insert(
                            name.clone(),
                            TypedDictEntry {
                                is_required: false,
                                ..entry.clone()
                            },
                        );
                    }
                }

                new_type = ClassType::clone_as_instance(
                    ClassType::clone_for_narrowed_typed_dict_entries(
                        ClassType(new_type),
                        Some(narrowed_entries_map),
                    ),
                    true,
                )
                .0;
            }

            // If it's a keyword parameter that has been assigned a value through
            // the "partial" mechanism, mark it has having a default value.
            let mut new_default_type =
                FunctionType::get_param_default_type(specialized_function_type, index as i32);
            if param
                .name
                .as_deref()
                .is_some_and(|name| !name.is_empty() && param_map.get(name) == Some(&true))
            {
                new_default_type = Some(AnyType::create(/* isEllipsis */ true).0);
            }
            FunctionParam::create(
                param.category,
                new_type,
                param.flags,
                param.name.as_deref(),
                new_default_type,
                None,
            )
        })
        .collect();
    let unassigned_param_list = updated_param_list.iter().filter(|param| {
        if param.category == ParamCategory::KwargsDict {
            return false;
        }
        if param.category == ParamCategory::ArgsList {
            return true;
        }
        match param.name.as_deref() {
            None | Some("") => true,
            Some(name) => !param_map.contains_key(name),
        }
    });
    let assigned_keyword_param_list = updated_param_list.iter().filter(|param| {
        param
            .name
            .as_deref()
            .is_some_and(|name| !name.is_empty() && param_map.get(name) == Some(&true))
    });
    let kwargs_param = updated_param_list
        .iter()
        .filter(|param| param.category == ParamCategory::KwargsDict);

    let mut new_param_list: Vec<FunctionParam> = Vec::new();
    new_param_list.extend(unassigned_param_list.cloned());
    new_param_list.extend(assigned_keyword_param_list.cloned());
    new_param_list.extend(kwargs_param.cloned());

    // Create a new __call__ method that uses the remaining parameters.
    let partial_shared = partial_call_member_type.d().shared.get();
    let specialized_doc_string = specialized_shared.cold().doc_string.clone();
    let new_call_member_type = FunctionType::create_instance(
        &partial_shared.name,
        &partial_shared.full_name,
        &partial_shared.module_name,
        partial_shared.flags.get(),
        specialized_doc_string,
    );

    let first_partial_param = partial_shared.parameters.get().borrow().first().cloned();
    if let Some(first_partial_param) = first_partial_param {
        FunctionType::add_param(new_call_member_type, &first_partial_param);
    }
    for param in &new_param_list {
        FunctionType::add_param(new_call_member_type, param);
    }

    let new_shared = new_call_member_type.d().shared.get();
    new_shared.declared_return_type.set(
        if specialized_shared.declared_return_type.get().is_some() {
            FunctionType::get_effective_return_type(specialized_function_type, true)
        } else {
            specialized_shared
                .cold().inferred_return_type
                .as_ref()
                .map(|inferred_return_type| inferred_return_type.type_)
        },
    );
    new_shared.declaration.set(partial_shared.declaration.get());
    let specialized_type_var_scope_id = *specialized_shared.type_var_scope_id.borrow();
    *new_shared.type_var_scope_id.borrow_mut() = specialized_type_var_scope_id;

    Some(FunctionResult {
        return_type: new_call_member_type.0,
        is_type_incomplete: false,
        argument_errors,
    })
}
